// FUNCTION: BFME2 0x0033A7F7 size=54 name=?popCount@@YAHI@Z evidence=N:ledger tier=A
int popCount(unsigned int value)
{
	unsigned int v = value - ((value >> 1) & 0x55555555u);
	unsigned int w = (v >> 2) & 0x33333333u;
	v &= 0x33333333u;
	w += v;
	unsigned int sum = ((w >> 4) + w) & 0x0F0F0F0Fu;
	return (int)((sum * 0x01010101u) >> 24);
}

