void ThingTemplate::validate()
{
	if (m_shadowTexture.isEmpty())
	{
		// no texture given, pick a default
		if (m_geometryInfo.usePluralShadowName())
			m_shadowTexture.set("shadows");
		else
			m_shadowTexture.set("shadow");
	}

	if (m_displayNameStrategic.isEmpty())
		m_displayNameStrategic.set(m_displayName);

	if (m_descriptionStrategic.isEmpty())
		m_descriptionStrategic.set(m_description);
}

