// A create-a-hero object shows its own button image; everything else its template's.
const Image *getButtonImage(ThingTemplate *thingTemplate, Object *object)
{
	if (thingTemplate == NULL || object == NULL)
		return NULL;
	if (object->getTemplate()->isKindOf(KINDOF_CREATE_A_HERO))
	{
		CreateAHeroData *hero = TheCreateAHeroManager->rva002197A6(object->getID());
		if (hero && hero->m_buttonImage)
			return hero->m_buttonImage;
	}
	return thingTemplate->getButtonImage();
}

