// FUNCTION: BFME2 0x0033BB04 size=335 name=?isEquivalentTo@ThingTemplate@@QBE_NPBV1@@Z evidence=N:ledger tier=A
// Zero Hour's (build variations both ways); BFME 2 first checks the EquivalentTo names both ways (old body's order).
Bool ThingTemplate::isEquivalentTo(const ThingTemplate *tt) const
{
	if (!(this && tt))
		return false;
	if (this == tt)
		return true;
	// Overridable's inline walk (its out-of-line copy is 0x001E3611), not ThingTemplate::getFinalOverride 0x0033A68A.
	if (this->Overridable::getFinalOverride() == tt->Overridable::getFinalOverride())
		return true;

	const AsciiString &thisName = m_name;
	std::vector<AsciiString>::const_iterator thisEnd = m_equivalentTo.end();
	std::vector<AsciiString>::const_iterator it;
	for (it = m_equivalentTo.begin(); it != thisEnd; ++it)
		if (it->compareNoCase(tt->m_name) == 0)
			return true;

	std::vector<AsciiString>::const_iterator jt = tt->m_equivalentTo.begin();
	std::vector<AsciiString>::const_iterator otherEnd = tt->m_equivalentTo.end();
	for (; jt != otherEnd; ++jt)
	{
		if (jt->compareNoCase(thisName) == 0)
			return true;
		for (it = m_equivalentTo.begin(); it != thisEnd; ++it)
			if (it->compareNoCase(*jt) == 0)
				return true;
	}

	Int i;
	Int numVariations = m_buildVariations.size();
	for (i = 0; i < numVariations; ++i)
		if (m_buildVariations[i].compareNoCase(tt->m_name) == 0)
			return true;

	numVariations = tt->m_buildVariations.size();
	for (i = 0; i < numVariations; ++i)
		if (tt->m_buildVariations[i].compareNoCase(thisName) == 0)
			return true;

	return false;
}

