// FUNCTION: BFME2 0x0033C807 size=67 name=?clearModuleDataWithTag@ModuleInfo@@QAE_NABVAsciiString@@AAV2@@Z evidence=N:ledger tier=A
Bool ModuleInfo::clearModuleDataWithTag(const AsciiString &tagToClear, AsciiString &clearedModuleNameOut)
{
	Bool removedAny = false;
	_STL::vector<Nugget>::iterator nugget = m_info.begin();
	while (nugget != m_info.end())
	{
		if (nugget->m_moduleTag == tagToClear)
		{
			// report the module's name, then drop its block
			clearedModuleNameOut = nugget->first;
			nugget = m_info.erase(nugget);
			removedAny = true;
			continue;
		}
		++nugget;
	}
	return removedAny;
}

