// FUNCTION: BFME2 0x0033C882 size=51 name=?clearAiModuleInfo@ModuleInfo@@QAE_NXZ evidence=N:ledger tier=A
Bool ModuleInfo::clearAiModuleInfo()
{
	Bool removedAny = false;
	_STL::vector<Nugget>::iterator nugget = m_info.begin();
	while (nugget != m_info.end())
	{
		if (nugget->second->isAiModuleData())
		{
			nugget = m_info.erase(nugget);
			removedAny = true;
			continue;
		}
		++nugget;
	}
	return removedAny;
}

