// FUNCTION: BFME2 0x0033EA47 size=118 name=?parsePrerequisiteUnit@@YAXPAVINI@@PAX1PBX@Z evidence=N:ledger tier=A
void parsePrerequisiteUnit(INI *ini, void *instance, void * /*store*/, const void * /*userData*/)
{
	std::vector<ProductionPrerequisite> *v = (std::vector<ProductionPrerequisite> *)instance;

	ProductionPrerequisite prereq;
	Bool orUnitWithPrevious = FALSE;
	for (const char *token = ini->getNextToken(); token != NULL; token = ini->getNextTokenOrNull())
	{
		prereq.addUnitPrereq(AsciiString(token), orUnitWithPrevious);
		orUnitWithPrevious = TRUE;
	}

	v->push_back(prereq);
}

// FUNCTION: BFME2 0x0033EABD size=93 name=?parsePrerequisiteScience@@YAXPAVINI@@PAX1PBX@Z evidence=N:ledger tier=A
void parsePrerequisiteScience(INI *ini, void *instance, void * /*store*/, const void * /*userData*/)
{
	std::vector<ProductionPrerequisite> *v = (std::vector<ProductionPrerequisite> *)instance;

	ProductionPrerequisite prereq;
	prereq.addSciencePrereq(INI::scanScience(ini->getNextToken()));

	v->push_back(prereq);
}

// FUNCTION: BFME2 0x0033EB1A size=93 name=?parsePrerequisiteUpgrade@@YAXPAVINI@@PAX1PBX@Z evidence=N:ledger tier=A
// The upgrade lookup by name (0x0033970D, beside INI::scanScience).
const UpgradeTemplate *bfmeFindUpgradeByName(const char *name);

void parsePrerequisiteUpgrade(INI *ini, void *instance, void * /*store*/, const void * /*userData*/)
{
	std::vector<ProductionPrerequisite> *v = (std::vector<ProductionPrerequisite> *)instance;

	ProductionPrerequisite prereq;
	prereq.addUpgradePrereq(bfmeFindUpgradeByName(ini->getNextToken()));

	v->push_back(prereq);
}

// FUNCTION: BFME2 0x0033EB77 size=51 name=?erasePrereqVec@Rva0033EB77Vec@@QAEPAXPAX0@Z evidence=?:placeholder tier=A

